-- Catalog search at tens of thousands of products: trigram indexes for the
-- word-by-word search generated by apps/api/src/catalog/catalog-search-sql.ts.
--
-- Every word of a query is matched against the article + name document
-- (search_text_folded) as a substring (ILIKE '%word%'), a measurement regex
-- (~*) or a close spelling (<%, pg_trgm word similarity), and an article
-- fragment is matched inside sku_normalized (LIKE '%914 2%' style). All of
-- these are answered by a pg_trgm GIN index; without one PostgreSQL scans
-- and re-evaluates every product row per query (measured ~1-3 s at 50k
-- rows on a laptop, see docs/SEARCH_AND_EXTERNAL_MATCHING.md).
--
-- Forward-only, additive: two indexes, no data change.

CREATE INDEX products_search_text_folded_trgm_idx
  ON app.products USING gin (search_text_folded gin_trgm_ops);

CREATE INDEX products_sku_normalized_trgm_idx
  ON app.products USING gin (sku_normalized gin_trgm_ops);
